INSERT INTO `posts` VALUES (115,542,189,NULL,NULL,'📢 Chères familles, chers élèves,\\n\\nNous sommes heureux de vous accueillir pour l\'année scolaire 2025-2026 au Lycée ESRMI. Cette année s\'annonce riche en projets et en défis. Ensemble, nous viserons l\'excellence.',1,1,'school',NULL,0,42,8,12,'2026-05-30 12:52:21','2026-05-30 12:52:21',NULL),(116,542,189,NULL,NULL,'Les conseils de classe du 2ème trimestre se tiendront du 5 au 9 mai. Les bulletins seront disponibles sur l\'espace numérique sous 48h après chaque conseil.',1,1,'school',NULL,0,28,5,13,'2026-05-30 12:52:21','2026-05-30 12:52:21',NULL),(117,543,189,32,NULL,'DM n°6 — Suites numériques et raisonnement par récurrence\\n\\nÀ rendre pour le vendredi 9 mai. Exercices prioritaires : 3, 4 et 6. Barème disponible sur l\'espace classe.',0,0,'group',NULL,0,18,12,10,'2026-05-30 12:52:21','2026-05-30 12:52:21',NULL),(118,544,189,29,NULL,'Rappel : contrôle de Physique-Chimie jeudi 8 mai. Chapitres concernés : Électricité (1-3) et Mécanique newtonienne. Fiches de révision déposées dans l\'espace classe.',0,0,'group',NULL,0,14,7,6,'2026-05-30 12:52:21','2026-05-30 12:52:21',NULL),(119,545,189,34,NULL,'Compte-rendu TP n°4 — Immunologie : à remettre avant le 12 mai. Consignes de rédaction dans l\'espace SVT. Les binômes non rendus auront un zéro.',0,0,'group',NULL,0,11,4,7,'2026-05-30 12:52:21','2026-05-30 12:52:21',NULL),(120,547,189,NULL,NULL,'Lecture conseillée pour les élèves du bac : \"L\'Amour de loin\" de Leïla Slimani. Un exemplaire est disponible à la bibliothèque. Résumé et analyse à la prochaine session.',0,0,'school',NULL,0,22,9,3,'2026-05-30 12:52:21','2026-05-30 12:52:21',NULL),(121,549,189,35,NULL,'Résultats du contrôle SEG — moyenne de classe : 13,4/20. Très bonne performance ! Correction détaillée projetée lundi en cours.',0,0,'group',NULL,0,18,6,14,'2026-05-30 12:52:22','2026-05-31 18:21:08',NULL),(122,542,189,NULL,NULL,'Nous félicitons nos élèves qui ont représenté ESRMI au Concours National de Sciences 2025 ! Mention spéciale à l\'équipe de 2ème Bac SM qui a décroché la 2ème place régionale. Bravo !',1,1,'school',NULL,0,86,14,4,'2026-05-30 12:52:22','2026-05-30 12:52:22',NULL),(123,543,189,37,NULL,'Correction du bac blanc : les copies sont disponibles. RDV jeudi 8h pour la reprise collective. Focus sur l\'analyse complexe et la trigonométrie.',0,0,'group',NULL,0,21,8,13,'2026-05-30 12:52:22','2026-05-31 18:36:06',NULL),(124,550,189,NULL,NULL,'English Corner — chaque mercredi de 13h à 14h en salle 12. Tous niveaux bienvenus. Programme : conversation, actualités, préparation aux certifications.',0,0,'school',NULL,0,31,11,15,'2026-05-30 12:52:22','2026-05-30 12:52:22',NULL),(125,542,189,NULL,NULL,'Hello',0,1,'school',0,0,2,1,0,'2026-05-31 18:20:23','2026-05-31 18:20:34',NULL),(126,542,189,NULL,NULL,'',0,1,'school',0,0,2,0,0,'2026-05-31 18:37:08','2026-05-31 18:41:38',NULL),(127,542,189,NULL,NULL,'',0,1,'school',0,0,2,0,0,'2026-05-31 18:49:05','2026-05-31 18:49:27',NULL),(128,542,189,NULL,NULL,'Hello',0,1,'school',0,0,0,0,0,'2026-05-31 18:49:40','2026-05-31 18:49:41',NULL),(129,542,189,NULL,NULL,'this is me and platon',0,1,'school',0,0,0,0,0,'2026-05-31 19:37:13','2026-05-31 19:37:13',NULL);
